<form method="get" action="<?php echo e(base_url('index.php'));?>" style="overflow:hidden;"><input type="hidden" name="page" value="customer"><input type="hidden" name="section" value="browse"><div style="float:left;width:70%;"><input type="text" name="q" value="<?php echo e($q);?>" placeholder="Search products..." style="width:100%;padding:12px;"></div><div style="float:left;width:28%;margin-left:2%;"><button class="btn btn-primary btn-block">Search</button></div><div class="clear"></div></form><?php if($q!==''):?><p class="small muted mt">Results for "<?php echo e($q);?>" — <a href="<?php echo e(url_for('customer','browse'));?>">clear</a></p><?php endif;?></div>
